mapper.select:
select id, tenant_id, material_id, depot_id, warning_type, active,
       current_stock, notify_time, create_time, update_time
from jsh_stock_warning_status
where tenant_id = #{tenantId}
  and material_id = #{materialId}
  and depot_id = #{depotId}
  and warning_type = #{warningType}
for update
